import java.util.*;

import lombok.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        Set<Akun> semua = new LinkedHashSet<>();
        while (in.hasNextLine()) {
            String[] d = in.nextLine().split(";");
            semua.add(new Akun(d[0], d[1], d[2]));
        }
        for (Akun a : semua) {
            System.out.println(a);
        }
        System.out.println("Jumlah akun: " + semua.size());
    }
}

@ToString
@EqualsAndHashCode(onlyExplicitlyIncluded = true)
class Akun {
    @EqualsAndHashCode.Include
    private final String email;
    private final String nama;
    @ToString.Exclude
    private final String sandi;

    Akun(String email, String nama, String sandi) {
        this.email = email;
        this.nama = nama;
        this.sandi = sandi;
    }
